.header-fixed { position: fixed; top: 0; left: 0; right: 0; z-index: 50; transition: all 0.5s ease; }
.header-scrolled { background-color: rgba(10,10,10,0.95); backdrop-filter: blur(10px); }
.nav-link { font-size: 0.75rem; font-weight: 600; letter-spacing: 0.15em; text-transform: uppercase; color: #9a836e; text-decoration: none; transition: color 0.3s ease; }
.nav-link:hover { color: #fafaf9; }
.btn-primary { display: inline-flex; align-items: center; justify-content: center; padding: 1rem 2rem; background-color: #e8e2d8; color: #0a0a0a; font-weight: 500; font-size: 0.875rem; letter-spacing: 0.05em; transition: background-color 0.3s ease; text-decoration: none; cursor: pointer; }
.btn-primary:hover { background-color: #d1c5b3; }
.btn-secondary { display: inline-flex; align-items: center; justify-content: center; padding: 1rem 2rem; border: 1px solid #4a3a33; color: #d1c5b3; font-weight: 500; font-size: 0.875rem; letter-spacing: 0.05em; transition: all 0.3s ease; text-decoration: none; cursor: pointer; background: transparent; }
.btn-secondary:hover { background-color: #4a3a33; }
.tech-label-corner { position: absolute; font-size: 0.625rem; text-transform: uppercase; letter-spacing: 0.2em; padding: 0.25rem 0.5rem; background-color: rgba(10,10,10,0.9); backdrop-filter: blur(8px); color: #9a836e; border: 1px solid rgba(90,70,60,0.5); box-shadow: 0 10px 15px -3px rgba(0,0,0,0.1); font-family: 'Courier New', monospace; z-index: 20; pointer-events: none; white-space: nowrap; }
.tech-label-tl { top: 0.5rem; left: 0.5rem; } .tech-label-br { bottom: 0.5rem; right: 0.5rem; }
.product-frame-border { position: absolute; inset: -4px; border: 1px solid rgba(90,70,60,0.2); pointer-events: none; }
.product-corner-bracket { position: absolute; width: 12px; height: 12px; pointer-events: none; }
.product-corner-tl { top: -1px; left: -1px; border-top: 1px solid rgba(148,130,110,0.3); border-left: 1px solid rgba(148,130,110,0.3); }
.product-corner-tr { top: -1px; right: -1px; border-top: 1px solid rgba(148,130,110,0.3); border-right: 1px solid rgba(148,130,110,0.3); }
.product-corner-bl { bottom: -1px; left: -1px; border-bottom: 1px solid rgba(148,130,110,0.3); border-left: 1px solid rgba(148,130,110,0.3); }
.product-corner-br { bottom: -1px; right: -1px; border-bottom: 1px solid rgba(148,130,110,0.3); border-right: 1px solid rgba(148,130,110,0.3); }
.product-cross-line { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; opacity: 0.1; pointer-events: none; }
.product-cross-line::before { content: ""; width: 1px; height: 100%; background-color: #6e584a; }
.section-label { display: inline-flex; align-items: center; gap: 0.5rem; font-size: 0.625rem; font-weight: 600; letter-spacing: 0.2em; text-transform: uppercase; color: #9a836e; }
.section-label::before { content: ""; display: block; width: 2rem; height: 1px; background-color: #4a3a33; }
@keyframes spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
@keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
@keyframes fadeInUp { from { opacity: 0; transform: translateY(12px); } to { opacity: 1; transform: translateY(0); } }
@keyframes scanLine { 0% { top: 0; opacity: 0; } 10% { opacity: 1; } 90% { opacity: 1; } 100% { top: 100%; opacity: 0; } }
@keyframes cornerPulse { 0%,100% { opacity: 0.35; } 50% { opacity: 0.7; } }
@keyframes floatUp { 0%,100% { transform: translateY(0); } 50% { transform: translateY(-4px); } }
.animate-spin { animation: spin 1s linear infinite; }
.animate-fade-in { animation: fadeIn 0.8s ease-out; }
.animate-fade-in-up { animation: fadeInUp 0.6s ease-out; }
.animate-scan { animation: scanLine 4s linear infinite; }
.animate-corner { animation: cornerPulse 3.5s ease-in-out infinite; }
.animate-float { animation: floatUp 4s ease-in-out infinite; }
.scan-line { position: absolute; left: 0; right: 0; height: 1px; background-color: rgba(148,130,110,0.2); z-index: 30; animation: scanLine 4s linear infinite; }
.mobile-menu-overlay { position: fixed; inset: 0; z-index: 60; background-color: #0a0a0a; display: flex; flex-direction: column; padding: 1.5rem; }
.lang-toggle { display: flex; align-items: center; gap: 0.5rem; font-size: 0.75rem; font-weight: 600; letter-spacing: 0.15em; }
.lang-btn { cursor: pointer; color: #9a836e; transition: color 0.2s ease; background: none; border: none; padding: 0; font-size: inherit; font-family: inherit; }
.lang-btn:hover { color: #fafaf9; } .lang-btn-active { color: #fafaf9; }
.lang-separator { color: #4a3a33; }
.hero-section { min-height: 100svh; background-color: #0a0a0a; padding-top: 72px; padding-bottom: 4rem; display: flex; flex-direction: column; justify-content: center; overflow: hidden; }
.launcher-section { position: relative; padding-top: 6rem; padding-bottom: 8rem; background-color: #050505; overflow: hidden; }
.cta-section { position: relative; padding-top: 6rem; padding-bottom: 8rem; background-color: #0a0a0a; border-top: 1px solid rgba(90,70,60,0.3); overflow: hidden; }
.footer-section { padding-top: 2rem; padding-bottom: 2rem; background-color: #0a0a0a; border-top: 1px solid rgba(90,70,60,0.3); }
::-webkit-scrollbar { width: 8px; } ::-webkit-scrollbar-track { background: #0a0a0a; } ::-webkit-scrollbar-thumb { background: #4a3a33; } ::-webkit-scrollbar-thumb:hover { background: #5a463c; }
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { animation-duration: 0.01ms !important; transition-duration: 0.01ms !important; } html { scroll-behavior: auto; } }

body.script:
(function() {
  var viData = {"layout":{"navHeight":"72px","heroHeight":"100svh","baseFontSize":"16px"},"links":{"facebook":"https://www.facebook.com/profile.php?id=61590708082215","zalo":"https://zalo.me/"},"nav":{"projects":"Dự án","launcher":"9Flip","about":"Giới thiệu","contact":"Liên hệ"},"hero":{"headline":"Công nghệ được làm lại theo cách thiết thực hơn.","subheadline":"Phần mềm và những dự án phần cứng độc bản","cta":"KHÁM PHÁ SẢN PHẨM"},"launcher":{"sectionTitle":"PHẦN MỀM NỔI BẬT","title":"9 Flip Launcher","description":"Mở ứng dụng trên màn hình ngoài Galaxy Z Flip.","features":[{"title":"Không Root","desc":"Giữ nguyên bảo hành, Knox nguyên vẹn."},{"title":"Dễ cài đặt","desc":"Có sẵn trên Google Play."},{"title":"Google Account","desc":"Premium theo tài khoản."},{"title":"Large Community","desc":"Cộng đồng đông đảo."}],"cta":"TẢI TRÊN GOOGLE PLAY"},"products":{"sectionTitle":"DỰ ÁN PHẦN CỨNG","viewDetails":"Xem chi tiết"},"brandStory":{"sectionTitle":"VỀ MIXED TECHNOLOGY","title":"Mỗi dự án đều bắt đầu từ rất nhiều bản phác thảo","description":"Tại Mixed Technology, chúng tôi kiến tạo trải nghiệm."},"cta":{"title":"SẴN SÀNG TRẢI NGHIỆM CÙNG MIXED TECHNOLOGY?","description":"Dù bạn đang tìm kiếm giải pháp","ctaFacebook":"NHẮN TIN FANPAGE","ctaZalo":"KẾT BẠN ZALO"},"footer":{"copyright":"Mixed Technology"},"images":{"hero":"/images/hero.jpg","launcher":"/images/launcher-mockup.jpg","story":"/images/story.jpg","products":["/images/product-1.jpg","/images/product-2.jpg","/images/product-3.jpg","/images/product-4.jpg","/images/product-5.jpg","/images/product-6.jpg"]}};
  var currentLang = localStorage.getItem('mixed_lang') || 'vi';
  function setLang(lang) { localStorage.setItem('mixed_lang', lang); location.reload(); }
  var viBtn = document.getElementById('lang-vi'); var enBtn = document.getElementById('lang-en');
  if (viBtn) viBtn.className = 'lang-btn' + (currentLang === 'vi' ? ' lang-btn-active' : '');
  if (enBtn) enBtn.className = 'lang-btn' + (currentLang === 'en' ? ' lang-btn-active' : '');
  window.toggleMobileMenu = function() { var m = document.getElementById('mobile-menu'); if (m) m.classList.toggle('hidden'); };
  window.addEventListener('scroll', function() { var h = document.getElementById('header'); if (h) { if (window.scrollY > 20) h.classList.add('header-scrolled'); else h.classList.remove('header-scrolled'); } });
})();
